/**
 * @file The MUI bridge — the AmberX theme engine, expressed as an MUI theme.
 *
 * This is the contract every surface built from here on depends on (owner,
 * 2026-08-09: everything future is MUI), so it is worth being explicit about
 * what it is and, more importantly, what it is NOT.
 *
 * It is **one more consumer of the engine that already exists**. It reads the
 * live `ThemeValues` and returns an MUI `Theme`. It does not own state, does
 * not persist anything, does not boot, and has no key of its own. `ThemeStore`
 * is still the only store, `THEME_KEY` still the only persistence key,
 * `themeBootScript()` still the only pre-paint path, and `AxfStyleRoot` still
 * the only writer of `:root`. A second store here would be the two-publishers
 * bug (`resolve.ts`) rebuilt one layer up, where it would be harder to see.
 *
 * It consumes `themeVariables()` rather than reading dials directly, and that
 * is deliberate: the type ramp, the shadow, the padding and the selection
 * colour are DERIVED (`derived.ts`), and computing them a second time here is
 * how an MUI `<Paper>` ends up a pixel off the card beside it. One derivation,
 * two renderings.
 *
 * ## The colour-parsing trap, and the choice made about it
 *
 * MUI runs real colour maths over palette entries — `augmentColor` calls
 * `getContrastText` → `getContrastRatio` → `decomposeColor`, and `alpha()` /
 * `darken()` / `lighten()` do the same inside component styles. `decomposeColor`
 * understands `#hex`, `rgb()`, `hsl()` and `color()`, and nothing else. So
 * handing `createTheme` a `var(--axf-accent)` is not a degraded-but-working
 * arrangement; it throws, at theme construction, taking the app with it.
 *
 * Two ways out were available. **Resolved values won.** Measured, not assumed
 * (`test/mui-bridge.test.ts` runs both):
 *
 * | | `createTheme({palette:{primary:{main:"var(--axf-accent)"}}})` |
 * |---|---|
 * | plain | throws ``MUI: Unsupported `var(--axf-accent)` color.`` |
 * | `cssVariables: true` | throws the SAME error |
 *
 * That measurement is the whole reason for the choice, and it is the opposite
 * of what "use v9's cssVariables mode and map `--axf-*` onto it" assumes.
 * cssVariables mode does not accept variable references as INPUT — it emits
 * `--mui-*` variables as OUTPUT, and to emit them it must first parse the real
 * colours (it computes `palette.primary.mainChannel = "255 122 26"`, which is
 * `decomposeColor` again). It cannot dodge a trap that is upstream of it.
 *
 * So cssVariables mode was rejected for what it would actually have cost:
 *
 *   1. **It solves nothing here.** Real values are still required at
 *      construction, so the "hard" half of the work is identical either way.
 *   2. **It creates a second variable namespace.** `--mui-palette-primary-main`
 *      would sit beside `--axf-accent` carrying the same value from the same
 *      source. This project has already paid for two writers of one property
 *      once, and the entire architecture of `resolve.ts` is the receipt.
 *      Publishing the truth twice is not a feature; it is the next version of
 *      that bug, with a rename.
 *   3. **A theme roll would have to update both.** `AxfStyleRoot` writes
 *      `--axf-*` imperatively and diffs; MUI's generated `--mui-*` block is a
 *      stylesheet regenerated by `createTheme`. Keeping two publication
 *      mechanisms in step across a roll is exactly the ordering race the
 *      engine already removed.
 *
 * What resolved values cost instead, stated honestly: a roll re-creates the MUI
 * theme object and Emotion re-generates MUI's class names. That is real work,
 * but it happens on a theme roll — a deliberate, human-frequency event — and it
 * is a normal React update, not a remount and not a reload. `token()` surfaces
 * still repaint from the custom properties alone, untouched.
 *
 * ## The hydration seam is inherited, not rebuilt
 *
 * `AxfMuiRoot` reads through `useTheme()`, so it rides on `ThemeStore.
 * serverState()` — the server render and the hydrating client render both see
 * the DEFAULT theme, and the persisted one arrives one commit later as an
 * ordinary update. That fix was paid for once (see `ThemeStore.serverState`)
 * and this bridge must never route around it by reading the store directly.
 */
import { createTheme } from "@mui/material/styles";
import type { Shadows, Theme } from "@mui/material/styles";

import { themeVariables } from "./apply";
import { shadowFor } from "./derived";
import { luminance } from "./color";
import { DIALS, defaultValues } from "./spec";
import type { ThemeValues } from "./spec";

/* -------------------------------------------------------------- the map --- */

/**
 * Every dial, and where it lands in MUI. `muiPath` is `null` when MUI has no
 * counterpart — and then `why` is mandatory.
 *
 * This exists because **a dial silently dropped is a dial that looks broken to
 * whoever turns it later**. A designer who moves `navPlacement` and sees
 * nothing happen on an MUI surface needs to find out here that MUI has no
 * concept of a nav menu, rather than concluding the engine is broken.
 *
 * It is also the discovering guard: `test/mui-bridge.test.ts` walks `DIALS` and
 * fails on any dial with no entry here, so a dial added to the spec cannot be
 * omitted from this map in silence. That is the same property `DIALS` already
 * gives the generator and the applier.
 */
export interface DialMapping {
  readonly dialId: string;
  /** Dotted path into the MUI theme, or `null` when there is no counterpart. */
  readonly muiPath: string | null;
  /** How it is carried, or — when `muiPath` is null — why nothing carries it. */
  readonly note: string;
}

export const MUI_DIAL_MAP: readonly DialMapping[] = [
  /* ------------------------------------------------------------- palette -- */
  {
    dialId: "page",
    muiPath: "palette.background.default + palette.mode",
    note:
      "The base surface. Also DECIDES palette.mode by luminance — MUI picks its own " +
      "defaults (text.disabled, divider fallbacks, contrast text) from the mode, so a " +
      "light page under a dark mode produces unreadable defaults everywhere MUI fills a gap."
  },
  { dialId: "panel", muiPath: "palette.background.paper", note: "Card and pane background — MUI's second and last surface." },
  {
    dialId: "panel2",
    muiPath: "palette.action.hover",
    note:
      "MUI's `background` has exactly two entries, so there is nowhere for a third " +
      "surface. action.hover is where MUI actually paints hovered rows, menu items and " +
      "table headers — the same job panel2's own effect line names — so the raised " +
      "surface lands there rather than being dropped for want of a background slot."
  },
  { dialId: "ink", muiPath: "palette.text.primary", note: "Body text." },
  { dialId: "dim", muiPath: "palette.text.secondary", note: "Secondary text, labels, captions." },
  { dialId: "edge", muiPath: "palette.divider", note: "Borders and dividers." },
  { dialId: "accent", muiPath: "palette.primary.main", note: "The brand colour. MUI derives light/dark/contrastText from it." },
  { dialId: "accent2", muiPath: "palette.secondary.main", note: "The secondary voice." },
  {
    dialId: "accent3",
    muiPath: null,
    note:
      "MUI's palette has exactly TWO brand voices — primary and secondary. There is no " +
      "tertiary, and adding `palette.accent3` would be inventing a counterpart rather " +
      "than mapping one. The dial still publishes `--axf-accent3` and the brand roles, " +
      "so packs and token() surfaces honour it; an MUI component that wants the third " +
      "voice reads token(\"accent3\") in its sx."
  },
  { dialId: "info", muiPath: "palette.info.main", note: "Informational status." },
  { dialId: "ok", muiPath: "palette.success.main", note: "Positive status." },
  { dialId: "warn", muiPath: "palette.warning.main", note: "Cautionary status." },
  { dialId: "err", muiPath: "palette.error.main", note: "Failure status." },

  /* ---------------------------------------------------------- typography -- */
  { dialId: "sans", muiPath: "typography.fontFamily", note: "The one family MUI models." },
  {
    dialId: "mono",
    muiPath: null,
    note:
      "MUI's typography has ONE fontFamily and no monospace slot — a mono face is set " +
      "per call site, not per theme. The dial publishes `--axf-mono`; an MUI surface " +
      "showing code or ids reads token(\"mono\") in its sx, exactly as a token() surface does."
  },
  {
    dialId: "sizeBody",
    muiPath: "typography.fontSize + the five mapped variants",
    note:
      "Sets MUI's base size, which scales every variant this bridge does NOT name " +
      "(h1–h4, subtitle, button, overline) through MUI's own coefficient — so those " +
      "follow the dial without a second ramp being invented for them."
  },
  {
    dialId: "scaleRatio",
    muiPath: "typography.{caption,body2,body1,h6,h5}.fontSize",
    note:
      "Carried INDIRECTLY and on purpose: the ratio is consumed by the derived size " +
      "ramp (--axf-size-micro…hero), and this bridge reads that ramp rather than " +
      "recomputing it. Turning the ratio moves the five mapped variants."
  },
  { dialId: "weightStrong", muiPath: "typography.fontWeightBold + h5/h6 weight", note: "Titles and emphasis." },
  {
    dialId: "tracking",
    muiPath: "typography.{caption,body2,body1,h6,h5,button}.letterSpacing",
    note:
      "MUI has no global letter-spacing key — tracking lives per variant. Written to " +
      "every variant this bridge sets, so one dial still governs, but the per-variant " +
      "shape is MUI's and is worth knowing before adding a sixth variant."
  },

  /* --------------------------------------------------------------- shape -- */
  { dialId: "radius", muiPath: "shape.borderRadius", note: "MUI's one radius; sx `borderRadius: n` multiplies it." },
  {
    dialId: "border",
    muiPath: null,
    note:
      "MUI has no global border-width. Its borders are literal `1px solid ${divider}` " +
      "strings inside component styles, so honouring this dial means component " +
      "overrides — a components-layer decision that belongs to the rebuild phases, not " +
      "to the palette bridge. Until then MUI surfaces draw 1px while token() surfaces " +
      "follow `--axf-border`; that is a real, known gap, recorded rather than papered over."
  },
  {
    dialId: "elevation",
    muiPath: "shadows[0..24]",
    note:
      "ONE dial expanded into MUI's 25-entry ramp via the SHARED `shadowFor()` from " +
      "derived.ts — level n is shadowFor(elevation × n / 6), so at the dial's default " +
      "of 6 MUI level 6 is exactly the engine's own `--axf-shadow`, the ramp scales " +
      "linearly with the dial, and 0 flattens everything to `none` on both sides."
  },

  /* ------------------------------------------------------------- density -- */
  {
    dialId: "density",
    muiPath: "components.{MuiButton,MuiTextField,MuiIconButton,MuiChip,MuiTable}.defaultProps.size",
    note:
      "MUI has no theme-level density scalar; `size` on a component IS its density " +
      "control, so the word maps to the default size rather than being recorded as " +
      "unmappable. Only the five components with a real small/medium size axis are set."
  },
  {
    dialId: "gap",
    muiPath: "spacing",
    note:
      "spacing = gap / 2, so theme.spacing(2) is exactly one gap and MUI's own " +
      "conventional 8px base falls out of the dial's 16px default unchanged."
  },

  /* -------------------------------------------------------------- layout -- */
  ...(
    [
      "navPlacement",
      "navStyle",
      "navSize",
      "navGlyph",
      "navIndicator",
      "navMotion",
      "navBackground",
      "navGap",
      "navLabelCase",
      "navAlign",
      "barScale",
      "barHeight",
      "barBackground",
      "contentWidth",
      "pagePad"
    ] as const
  ).map(
    (dialId): DialMapping => ({
      dialId,
      muiPath: null,
      note:
        "Describes AmberX's OWN chrome — the nav menu, the toolbars, the page frame. " +
        "MUI's theme models a component library, not an application shell: it has no " +
        "notion of where a nav menu lives or how tall a banner is, so there is nothing " +
        "to map onto. The dial reaches CSS as an `--axf-nav-*` / `--axf-bar-*` derived " +
        "token and core's chrome consumes it there. This is the largest block of " +
        "unmapped dials and it is unmapped by nature, not by omission."
    })
  ),

  /* ------------------------------------------------- layout, inside a module */
  ...(["gridColumns", "gridUnit", "gridGap", "surfacePad", "paneGutter"] as const).map(
    (dialId): DialMapping => ({
      dialId,
      muiPath: null,
      note:
        "Describes the interior of a MODULE — its card grid and its split panes. " +
        "Unmapped for a sharper reason than the chrome block above: MUI has no " +
        "component for either. `Grid` is a responsive twelve-column flow, not a " +
        "free-placement grid with per-card row/column spans, and there is no " +
        "split-pane component at all (the same absence `no-hand-rolled-ui.md` " +
        "grants PaneLayout its geometry exception for). So there is no theme path " +
        "to carry these even in principle. They publish as --axf-grid-* / " +
        "--axf-surface-pad / --axf-pane-gutter, and a module reads them — the " +
        "dashboard's grid reads the three grid dials through `useTheme()`, because " +
        "the column count drives placement MATH as well as CSS and the two must " +
        "not diverge."
    })
  ),

  /* -------------------------------------------------------------- motion -- */
  {
    dialId: "motionMs",
    muiPath: "transitions.duration.*",
    note:
      "MUI's seven named durations keep their relative ramp and are scaled so " +
      "`standard` equals the dial exactly. 0 zeroes all seven, so 'no motion' means " +
      "no motion on MUI surfaces too."
  },
  { dialId: "easing", muiPath: "transitions.easing.*", note: "The dial declares one curve; all four MUI easings take it." },

  /* -------------------------------------------------------------- chrome -- */
  {
    dialId: "bannerBar",
    muiPath: null,
    note:
      "Names the toolbar asset that draws the app banner. MUI has no counterpart " +
      "because this is not a style value at all — it is an ASSET id; the bar it " +
      "selects is rendered by toolbar/Toolbar, which builds from MUI primitives " +
      "that are themed like everything else."
  },
  {
    dialId: "navMenu",
    muiPath: null,
    note:
      "Names the nav-menu asset the shell places. Same reason as bannerBar — an " +
      "asset id, not a style value; presentation is the layout dials' job."
  },
  {
    dialId: "dashboard",
    muiPath: null,
    note:
      "Names the dashboard asset that wraps the screen. Same reason as bannerBar and " +
      "navMenu — an asset id, not a style value. The wrapper it selects publishes its " +
      "own --axd-* variables on its own element and drives MUI surfaces below it " +
      "through the `cards` dial, so what it does IS visible to MUI; none of it is a " +
      "value that could live on a MUI theme path."
  }
];

const MAPPING_BY_DIAL: ReadonlyMap<string, DialMapping> = new Map(
  MUI_DIAL_MAP.map((m) => [m.dialId, m])
);

/** Dials with no MUI counterpart, for any surface that wants to show the gap. */
export function unmappedDials(): readonly DialMapping[] {
  return MUI_DIAL_MAP.filter((m) => m.muiPath === null);
}

/** The mapping for one dial, or `undefined` if the spec has outgrown this map. */
export function mappingFor(dialId: string): DialMapping | undefined {
  return MAPPING_BY_DIAL.get(dialId);
}

/**
 * The other direction: MUI subsystems the engine does not drive.
 *
 * Recorded for the same reason as the unmapped dials. Somebody will eventually
 * ask "does rolling a theme change the breakpoints?", and the answer needs to
 * be written down where the mapping is rather than discovered by experiment.
 */
export const MUI_UNDRIVEN: readonly { subsystem: string; why: string }[] = [
  {
    subsystem: "breakpoints",
    why:
      "Responsive cut points are a layout contract, not a look. Rolling a theme must " +
      "not move where the app reflows — that would make a roll capable of breaking a " +
      "screen rather than restyling it. MUI's defaults stand."
  },
  {
    subsystem: "zIndex",
    why:
      "Stacking order is correctness, not taste: a rolled z-index could put a modal " +
      "behind its own backdrop. MUI's defaults stand, and core's own overlays " +
      "(ContextMenuRoot, ShellOverlays) sit above them by their own fixed values."
  },
  {
    subsystem: "mixins.toolbar",
    why:
      "AmberX's banner is a `toolbar` ASSET whose height comes from --axf-bar-thickness. " +
      "MUI's mixins.toolbar is for MUI's own AppBar, which this app does not use — " +
      "driving it would suggest the asset's geometry is negotiable, and it is not."
  }
];

/* ------------------------------------------------------------- resolving -- */

/**
 * Colours MUI can actually decompose. Deliberately NOT a permissive test: the
 * point is to refuse anything `decomposeColor` would throw on, and it throws on
 * everything not in this list — including plain CSS keywords like `white`,
 * which a hand-authored theme or a brand pack may legally contain.
 */
const PARSEABLE = /^(#[0-9a-fA-F]{3,8}|(?:rgb|rgba|hsl|hsla|color)\([^)]*\))$/;

const FALLBACK = defaultValues();

let warned = false;

/**
 * A colour MUI can do maths on, or the shipped default for that dial.
 *
 * The alternative is a white screen. `createTheme` throws on an unparseable
 * palette entry, and it is called during render of the app root — so one
 * `page: "white"` in a hand-authored theme or a branding pack would take down
 * every route, with a message about colour formats that names nothing the
 * author recognises. Falling back keeps the app up and keeps the failure
 * visible (the surface renders in the default colour, and dev gets a warning
 * naming the dial and the value).
 */
function colour(vars: Record<string, string>, name: string, fallbackTo?: string): string {
  const raw = vars[`--axf-${name}`];
  if (raw && PARSEABLE.test(raw.trim())) return raw.trim();
  // `--axf-selection` and `--axf-focus` are DERIVED tokens, not dials, so they
  // have no entry in defaultValues() — hence the explicit fallback argument.
  // Without it they would fall back to #000000, which is a black selection bar
  // that looks like a deliberate choice.
  const fallback = fallbackTo ?? String(FALLBACK[name] ?? "#000000");
  if (raw && !warned && typeof console !== "undefined") {
    warned = true;
    console.warn(
      `[axf/theme/mui] "${raw}" is not a colour MUI can decompose (token "${name}"). ` +
        `Falling back to ${fallback}. MUI parses #hex, rgb(), hsl() and color() only — ` +
        `a CSS keyword or a var() reference cannot be used in a palette entry.`
    );
  }
  return fallback;
}

/**
 * Which mode MUI should fill its own gaps from.
 *
 * `luminance()` reads a 6-digit hex by slicing, so it must not be handed the
 * `rgb()` / short-hex forms `PARSEABLE` legitimately admits — it would return
 * NaN and NaN > 0.5 is false, which is the right answer by accident and the
 * wrong one the day the comparison is reversed. Guarded and stated instead,
 * with dark as the default because the shipped theme is dark.
 */
const HEX6 = /^#[0-9a-fA-F]{6}$/;
function modeFor(page: string): "light" | "dark" {
  return HEX6.test(page) && luminance(page) > 0.5 ? "light" : "dark";
}

/** A published `13.5px` / `140ms` back to the number MUI wants. */
function unitless(vars: Record<string, string>, cssVar: string, fallback: number): number {
  const parsed = Number.parseFloat(vars[cssVar] ?? "");
  return Number.isFinite(parsed) ? parsed : fallback;
}

const SIZE_DEFAULTS: Record<string, "small" | "medium"> = {
  tight: "small",
  normal: "medium",
  airy: "medium"
};

/* ---------------------------------------------------------------- build --- */

/**
 * Build the MUI theme for a set of dial values — and, when one is active, the
 * pack layer those values are composed with.
 *
 * Pure — no DOM, no store, no globals — so it is unit-testable, usable in a
 * server render, and usable for a SUBTREE that wants its own theme (a live
 * preview beside the current theme, which is the thing `publish.ts` already
 * made possible for custom properties and this makes possible for MUI).
 *
 * ## Values only, since 2026-08-12
 *
 * This used to take the pack layer as a second `StyleInput` parameter — the
 * two-renderings contract, from the era when a selected pack could override
 * `--axf-accent` and the status colours. `resolve.ts` ended that: no pack may
 * touch an `--axf-*` value, so every colour MUI reads is a pure function of
 * the dials and the parameter had become dead weight that implied a
 * precedence that no longer exists. Deleting it (rather than ignoring it) is
 * what keeps the next reader from wiring the pack back in "for consistency".
 */
export function muiThemeFrom(values: ThemeValues): Theme {
  // The variable bag — dials AND derived tokens, from the one derivation.
  // Reading `values` directly here would mean re-deriving the type ramp and
  // the shadow, and two derivations of one thing is two answers.
  const vars = themeVariables(values);

  const page = colour(vars, "page");
  const ink = colour(vars, "ink");
  const accent = colour(vars, "accent");

  const mode = modeFor(page);

  const gap = unitless(vars, "--axf-gap", 16);
  const radius = unitless(vars, "--axf-radius", 8);
  const elevation = unitless(vars, "--axf-elevation", 6);
  const bodyPx = unitless(vars, "--axf-size-body", 13.5);
  const weightStrong = unitless(vars, "--axf-weight-strong", 700);
  const tracking = vars["--axf-tracking"] ?? "0.01em";
  const motionMs = unitless(vars, "--axf-motion", 140);
  const easing = vars["--axf-easing"] ?? "cubic-bezier(.2,.7,.3,1)";
  const density = String(values.density ?? "normal");
  const size = SIZE_DEFAULTS[density] ?? "medium";

  const face = vars["--axf-sans"] ?? "Inter, Segoe UI, system-ui, sans-serif";

  /** A variant's shape, from the derived ramp. One place, five callers. */
  const variant = (cssVar: string, weight?: number) => ({
    fontSize: vars[cssVar] ?? `${bodyPx}px`,
    letterSpacing: tracking,
    ...(weight === undefined ? {} : { fontWeight: weight })
  });

  // MUI's ramp keeps its relative proportions and is scaled so `standard`
  // lands exactly on the dial. 300 is MUI's own `standard`, i.e. the unit the
  // rest of its ramp is written against.
  const durationScale = motionMs / 300;
  const ms = (base: number) => Math.round(base * durationScale);

  return createTheme({
    palette: {
      mode,
      // Every entry below is a RESOLVED colour, never a var() — see the
      // docblock. `contrastText` is left to MUI, which computes it with
      // getContrastRatio against the value it was actually given.
      primary: { main: accent },
      secondary: { main: colour(vars, "accent2") },
      info: { main: colour(vars, "info") },
      success: { main: colour(vars, "ok") },
      warning: { main: colour(vars, "warn") },
      error: { main: colour(vars, "err") },
      background: { default: page, paper: colour(vars, "panel") },
      text: { primary: ink, secondary: colour(vars, "dim") },
      divider: colour(vars, "edge"),
      action: {
        hover: colour(vars, "panel2"),
        // The two derived tokens that already exist for exactly these jobs —
        // mapped so an MUI list row and a token() list row highlight alike.
        selected: colour(vars, "selection", accent),
        focus: colour(vars, "focus", accent)
      }
    },

    typography: {
      fontFamily: face,
      // The base MUI scales its UNNAMED variants from, so h1–h4 follow the
      // body dial without this bridge inventing a ramp for them.
      fontSize: bodyPx,
      fontWeightBold: weightStrong,
      caption: variant("--axf-size-micro"),
      body2: variant("--axf-size-label"),
      body1: variant("--axf-size-body"),
      h6: variant("--axf-size-title", weightStrong),
      h5: variant("--axf-size-hero", weightStrong),
      button: { letterSpacing: tracking, textTransform: "none" }
    },

    shape: { borderRadius: radius },

    // spacing(2) === one gap. See the mapping note.
    spacing: gap / 2,

    // One dial, MUI's 25 levels, ONE formula — `shadowFor` is imported rather
    // than re-implemented, so the ramp cannot drift from `--axf-shadow`.
    shadows: Array.from({ length: 25 }, (_, level) =>
      level === 0 ? "none" : shadowFor((elevation * level) / 6)
    ) as unknown as Shadows,

    transitions: {
      duration: {
        shortest: ms(150),
        shorter: ms(200),
        short: ms(250),
        standard: ms(300),
        complex: ms(375),
        enteringScreen: ms(225),
        leavingScreen: ms(195)
      },
      easing: { easeInOut: easing, easeOut: easing, easeIn: easing, sharp: easing }
    },

    components: {
      MuiButton: { defaultProps: { size } },
      MuiTextField: { defaultProps: { size } },
      MuiIconButton: { defaultProps: { size } },
      MuiChip: { defaultProps: { size } },
      MuiTable: { defaultProps: { size } }
    }
  });
}

/**
 * Dials the spec declares that this map has never heard of.
 *
 * Returned rather than thrown so a surface can display the gap; the test is
 * what makes it a gate. Empty is the only healthy answer.
 */
export function unmappedSpecDials(): readonly string[] {
  return DIALS.filter((d) => !MAPPING_BY_DIAL.has(d.id)).map((d) => d.id);
}
